/**
 * Operator-initiated, temporary DEV proof. No CLI imports, no public HTTP,
 * no native tool execution and no customer account/keys. This test's signed
 * envelope is generated by the owner-side fixture; NOT real device enrollment.
 * Stops automatically and clears files. Never used in production.
 */
import {DatabaseSync} from 'node:sqlite';
import {execFileSync} from 'node:child_process';
import {
  createHash,generateKeyPairSync,X509Certificate,randomBytes,
} from 'node:crypto';
import {readFileSync,writeFileSync,mkdtempSync,rmSync} from 'node:fs';
import {tmpdir} from 'node:os';
import path from 'node:path';
import {ProposedTrustedOwnerQuotaAuthority}
  from '../../src/product/trusted-owner-quota-authority-proposal.js';
import {startProposedOwnerQuotaLoopbackRpc,signDevOwnerQuotaRpcEnvelope}
  from '../../src/product/owner-quota-loopback-rpc-proposal.js';
import {startProposedOwnerQuotaOutboundWsHub}
  from '../../src/product/owner-quota-outbound-ws-proposal.js';

const ip=process.env.NEXOWIRE_DEV_TAILSCALE_IP??'';
if(!/^100\./.test(ip))throw new Error('DEV operator Tailnet IP required');
const dir=mkdtempSync(path.join(tmpdir(),'nexowire-tailnet-wss-'));
const readyFile=path.join(tmpdir(),'nexowire-tailnet-wss-readiness.json');
const certFile=path.join(dir,'dev.crt'),keyFile=path.join(dir,'dev.key');
let rpc:Awaited<ReturnType<typeof startProposedOwnerQuotaLoopbackRpc>>|undefined;
let ws:Awaited<ReturnType<typeof startProposedOwnerQuotaOutboundWsHub>>|undefined;
let db:DatabaseSync|undefined;
try{
  execFileSync('C:\\Program Files\\Git\\usr\\bin\\openssl.exe',[
    'req','-x509','-newkey','rsa:2048','-sha256','-nodes',
    '-keyout',keyFile,'-out',certFile,'-days','1',
    '-subj','/CN=Nexowire-DEV-Private-Only',
    '-addext','subjectAltName=IP:'+ip,
    '-addext','basicConstraints=critical,CA:TRUE',
  ],{stdio:'ignore',timeout:22000});
  const cert=readFileSync(certFile,'utf8');
  const key=readFileSync(keyFile,'utf8');
  const fp=new X509Certificate(cert).fingerprint256.replaceAll(':','').toLowerCase();
  const dev=generateKeyPairSync('ed25519');
  const publicDevice=dev.publicKey.export({format:'pem',type:'spki'}).toString();
  const privateDevice=dev.privateKey.export({format:'pem',type:'pkcs8'}).toString();
  const account='dev-tailnet-owner-account-001',device='dev-tailnet-device-001';
  const bearer=randomBytes(24).toString('base64url');
  db=new DatabaseSync(':memory:');
  for(const f of [
    'test/fixtures/scale-v2-owner-shared-quota-dev.sql',
    'test/fixtures/scale-v2-all-ingress-transport-staging.sql',
    'test/fixtures/scale-v2-owner-quota-rpc-dev.sql',
  ])db.exec(readFileSync(path.resolve(f),'utf8'));
  db.prepare('INSERT INTO proposed_owner_quota_accounts VALUES(?,?,?,?,?)')
    .run(account,'custom',100,1,1);
  db.prepare('INSERT INTO proposed_owner_quota_devices VALUES(?,?,?,?)')
    .run(device,account,1,'safe');
  db.prepare('INSERT INTO proposed_owner_rpc_device_keys VALUES(?,?,1)')
    .run(device,publicDevice);
  const auth=new ProposedTrustedOwnerQuotaAuthority(db,async t=>
    t===bearer?{accountId:account,sessionGeneration:1}:null);
  rpc=await startProposedOwnerQuotaLoopbackRpc({
    db,authority:auth,
    trustedToolCatalog:new Map([['tailnet-read-tool-0001',{
      operationClass:'read',
      toolFingerprint:createHash('sha256').update('DEV-tailnet-read').digest('hex'),
    }]]),
  });
  ws=await startProposedOwnerQuotaOutboundWsHub({
    trustedOwnerRpcOrigin:rpc.origin,
    stagingTailscaleIPv4:ip,
    tls:{certificatePem:cert,privateKeyPem:key},
  });
  const now=Date.now();
  const envelope=signDevOwnerQuotaRpcEnvelope({
    envelope:{
      version:1,
      deviceId:device,
      nonce:'dev-tailnet-nonce-'+randomBytes(12).toString('hex'),
      issuedAtMs:now,
      body:{
        bearerToken:bearer,
        invocationId:'dev-tailnet-call-'+randomBytes(12).toString('hex'),
        toolId:'tailnet-read-tool-0001',
      },
    },
    devicePrivateKeyPem:privateDevice,
  });
  writeFileSync(readyFile,JSON.stringify({
    url:ws.url,certPem:cert,sha256:fp,
    request:{version:1,kind:'reserve',
      requestId:'dev-wss-request-'+randomBytes(8).toString('hex'),
      envelope},
    issuedAtMs:now,
  }),'utf8');
  process.stdout.write('PRIVATE_WSS_READY '+ws.url+'\n');
  await new Promise<void>(resolve=>setTimeout(resolve,75_000));
}finally{
  try{await ws?.close()}catch{}
  try{await rpc?.close()}catch{}
  try{db?.close()}catch{}
  rmSync(readyFile,{force:true});
  rmSync(dir,{recursive:true,force:true});
}
